		var cmd tea.Cmd
		m.bar, cmd = m.bar.Update(msg)
		m.rebuildText()
		return m, cmd
	}

	switch msg.String() {
	case "esc":
		return m.goBack()
	case "f":
		m.toggleDisplay()
		return m, nil
	case "c":
		m.toggleHighlight()
		return m, nil
	case "ctrl+r":
		return m.reload()
	}

	if m.display == displayTree {
		return m.handleTreeKey(msg)
	}
	return m.handleTextKey(msg)
}"},{"rank":2,"score":90.6619,"file_path":"internal/ui/status/components/component_form.go","start_line":122,"end_line":148,"focus_line":124,"snippet_start_line":124,"snippet_end_line":148,"symbol_start_line":124,"symbol_end_line":148,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/ui/status/components/component_form.go:method:ComponentForm.handleKeyMsg","symbol_name":"handleKeyMsg","qualified_name":"ComponentForm.handleKeyMsg","signature":"func (f *ComponentForm) handleKeyMsg(msg tea.KeyMsg) (*ComponentForm, tea.Cmd)","signals":["body","exact-symbol","symbol-name","constraint:entity","exact-code-token","graph:callers","complete-symbol"],"snippet":"func (f *ComponentForm) handleKeyMsg(msg tea.KeyMsg) (*ComponentForm, tea.Cmd) {
